typedef struct Base Base;
typedef void (*Method)(Base* self);

// Virtual Table (Interface definition)
struct VTable {
    Method action;
    Method cleanup;
};

// Base Class (Structure containing VTable pointer)
struct Base {
    const struct VTable* vptr;
    int common_id;
};

// Derived Class (Inheritance via embedding Base first)
struct Derived {
    struct Base super;
    float specialized_data;
};

// VTable implementation for Derived type
void Derived_Action(Base* self) { /* ... */ }
const struct VTable Derived_VT = { Derived_Action, NULL };

// Polymorphic Dispatch
void execute(Base* obj) {
    obj->vptr->action(obj);
}
